'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, CsvError } = require('../src/csv.js');

function assertCsvError(fn, line, column, pattern) {
  assert.throws(fn, (err) => {
    assert.ok(err instanceof CsvError, `expected CsvError, got ${err && err.name}`);
    assert.ok(err instanceof Error);
    assert.equal(err.name, 'CsvError');
    assert.deepEqual({ line: err.line, column: err.column }, { line, column });
    if (pattern) assert.match(err.message, pattern);
    return true;
  });
}

describe('parse: arguments', () => {
  for (const [label, value] of [
    ['undefined', undefined],
    ['null', null],
    ['a number', 42],
    ['a Buffer', Buffer.from('a,b')],
    ['an array', ['a,b']],
    ['a String object', new String('a,b')],
  ]) {
    it(`throws TypeError when text is ${label}`, () => {
      assert.throws(() => parse(value), TypeError);
    });
  }

  it('returns [] for an empty string', () => {
    assert.deepEqual(parse(''), []);
    assert.deepEqual(parse('', { header: true }), []);
    assert.deepEqual(parse('', { skipEmptyLines: true }), []);
  });

  for (const [label, delimiter] of [
    ['empty', ''],
    ['two characters', ';;'],
    ['a surrogate pair', '\u{1F600}'],
    ['a double quote', '"'],
    ['CR', '\r'],
    ['LF', '\n'],
    ['a number', 1],
    ['null', null],
  ]) {
    it(`throws TypeError for a delimiter that is ${label}`, () => {
      assert.throws(() => parse('a', { delimiter }), TypeError);
    });
  }

  it('throws TypeError for options that are not an object', () => {
    assert.throws(() => parse('a', null), TypeError);
    assert.throws(() => parse('a', 'header'), TypeError);
  });

  it('throws TypeError for non-boolean header or skipEmptyLines', () => {
    assert.throws(() => parse('a', { header: 'yes' }), TypeError);
    assert.throws(() => parse('a', { skipEmptyLines: 1 }), TypeError);
  });

  it('ignores unknown options so one options object can serve parse and stringify', () => {
    assert.deepEqual(parse('a;b', { delimiter: ';', eol: '\n' }), [['a', 'b']]);
  });

  it('does not modify the options object', () => {
    const options = Object.freeze({ delimiter: ';', header: true });
    assert.deepEqual(parse('a;b\n1;2', options), [{ a: '1', b: '2' }]);
  });
});

describe('parse: fields and records', () => {
  it('splits fields on commas by default', () => {
    assert.deepEqual(parse('a,b,c'), [['a', 'b', 'c']]);
  });

  for (const delimiter of [';', '\t', '|', ' ', 'é']) {
    it(`splits fields on a custom delimiter ${JSON.stringify(delimiter)}`, () => {
      const text = ['a', 'b,c', ''].join(delimiter);
      assert.deepEqual(parse(text, { delimiter }), [['a', 'b,c', '']]);
    });
  }

  it('keeps empty fields at the start, middle and end of a record', () => {
    assert.deepEqual(parse(',a,,b,'), [['', 'a', '', 'b', '']]);
    assert.deepEqual(parse(','), [['', '']]);
    assert.deepEqual(parse(',\n'), [['', '']]);
  });

  it('separates records by CRLF, LF and CR, mixed in one input', () => {
    assert.deepEqual(parse('a\r\nb\nc\rd'), [['a'], ['b'], ['c'], ['d']]);
  });

  it('allows records with different field counts outside header mode', () => {
    assert.deepEqual(parse('a,b\nc\nd,e,f'), [['a', 'b'], ['c'], ['d', 'e', 'f']]);
  });

  it('never trims whitespace', () => {
    assert.deepEqual(parse(' a , b\t,\tc '), [[' a ', ' b\t', '\tc ']]);
    assert.deepEqual(parse('  \n'), [['  ']]);
  });

  it('treats a quote that is not at the start of a field as an ordinary character', () => {
    assert.deepEqual(parse('a"b,c",d""'), [['a"b', 'c"', 'd""']]);
    assert.deepEqual(parse(' "a",b'), [[' "a"', 'b']]);
  });

  it('keeps non-ASCII text, including astral characters and lone surrogates', () => {
    assert.deepEqual(parse('é,中文,\u{1F600}\n\uD800,"\uDFFF"'), [
      ['é', '中文', '\u{1F600}'],
      ['\uD800', '\uDFFF'],
    ]);
  });
});

describe('parse: line breaks and empty lines', () => {
  for (const eol of ['\r\n', '\n', '\r']) {
    const name = JSON.stringify(eol);

    it(`ignores one trailing ${name}`, () => {
      assert.deepEqual(parse(`a,b${eol}c,d${eol}`), [['a', 'b'], ['c', 'd']]);
    });

    it(`turns a second trailing ${name} into an empty record`, () => {
      assert.deepEqual(parse(`a${eol}${eol}`), [['a'], ['']]);
    });

    it(`reads a lone ${name} as one empty record`, () => {
      assert.deepEqual(parse(eol), [['']]);
      assert.deepEqual(parse(eol, { skipEmptyLines: true }), []);
    });
  }

  it('reads CR CR LF as a record end followed by one empty line', () => {
    assert.deepEqual(parse('a\r\r\nb'), [['a'], [''], ['b']]);
  });

  it('reads LF CR as two line breaks', () => {
    assert.deepEqual(parse('a\n\rb'), [['a'], [''], ['b']]);
  });

  it('keeps empty lines in the middle and at the start as [""]', () => {
    assert.deepEqual(parse('\na\n\n\nb'), [[''], ['a'], [''], [''], ['b']]);
  });

  it('skips every empty line with skipEmptyLines', () => {
    assert.deepEqual(parse('\r\na\n\n\rb\r\n\r\n', { skipEmptyLines: true }), [['a'], ['b']]);
  });

  it('does not skip lines that hold whitespace or a quoted empty field', () => {
    assert.deepEqual(parse(' \n""\n,', { skipEmptyLines: true }), [[' '], [''], ['', '']]);
  });
});

describe('parse: byte order mark', () => {
  it('ignores a leading BOM', () => {
    assert.deepEqual(parse('﻿a,b'), [['a', 'b']]);
    assert.deepEqual(parse('﻿"a"'), [['a']]);
  });

  it('returns [] for an input that is only a BOM', () => {
    assert.deepEqual(parse('﻿'), []);
  });

  it('keeps a BOM that is not the first character, and a second leading BOM', () => {
    assert.deepEqual(parse('a,﻿b\n﻿c'), [['a', '﻿b'], ['﻿c']]);
    assert.deepEqual(parse('﻿﻿a'), [['﻿a']]);
  });

  it('does not count the BOM as a column', () => {
    assertCsvError(() => parse('﻿"a"x'), 1, 4);
  });

  it('strips the BOM from the first header name', () => {
    assert.deepEqual(parse('﻿id\n1', { header: true }), [{ id: '1' }]);
  });
});

describe('parse: quoted fields', () => {
  it('keeps delimiters, CR, LF and CRLF inside quotes', () => {
    assert.deepEqual(parse('"a,b","c\nd","e\rf","g\r\nh"'), [['a,b', 'c\nd', 'e\rf', 'g\r\nh']]);
  });

  it('reads "" inside quotes as one literal quote', () => {
    assert.deepEqual(parse('"a""b","""","""x"""'), [['a"b', '"', '"x"']]);
  });

  it('reads an empty quoted field as an empty string', () => {
    assert.deepEqual(parse('"",""\n""'), [['', ''], ['']]);
  });

  it('ends a quoted field at a delimiter, a line break or the end of input', () => {
    assert.deepEqual(parse('"a",b\n"c"\r\n"d"\r"e"'), [['a', 'b'], ['c'], ['d'], ['e']]);
  });

  it('keeps whitespace inside quotes', () => {
    assert.deepEqual(parse('" a ","\t"'), [[' a ', '\t']]);
  });
});

describe('parse: input errors', () => {
  it('reports an unclosed quoted field at its opening quote', () => {
    assertCsvError(() => parse('a,"bc'), 1, 3, /unclosed/i);
    assertCsvError(() => parse('x\ny,"a\nb\n'), 2, 3);
    assertCsvError(() => parse('"'), 1, 1);
    assertCsvError(() => parse('"a""'), 1, 1);
  });

  it('reports a character after a closing quote at that character', () => {
    assertCsvError(() => parse('"a"b'), 1, 4, /after closing quote/);
    assertCsvError(() => parse('a,b\n"c" '), 2, 4);
    assertCsvError(() => parse('"a";b', { delimiter: ',' }), 1, 4);
  });

  it('counts line breaks inside quoted fields when reporting positions', () => {
    assertCsvError(() => parse('"a\r\nb"c'), 2, 3);
    assertCsvError(() => parse('"a\rb"c'), 2, 3);
    assertCsvError(() => parse('"a\n\rb"c'), 3, 3);
    assertCsvError(() => parse('"a\n\r\nb"c'), 3, 3);
  });

  it('counts columns in UTF-16 code units', () => {
    assertCsvError(() => parse('\u{1F600},"a"x'), 1, 7);
  });

  it('throws the first error a left-to-right read finds', () => {
    assertCsvError(() => parse('"a"x,"unclosed'), 1, 4);
  });

  it('includes the position in the message', () => {
    assertCsvError(() => parse('\n"a"x'), 2, 4, /line 2, column 4/);
  });
});

describe('parse: header mode', () => {
  it('keys later records by the header names', () => {
    assert.deepEqual(parse('id,name\r\n1,Ada\r\n2,"Lin, Bo"\r\n', { header: true }), [
      { id: '1', name: 'Ada' },
      { id: '2', name: 'Lin, Bo' },
    ]);
  });

  it('returns [] for a header with no records', () => {
    assert.deepEqual(parse('a,b', { header: true }), []);
    assert.deepEqual(parse('a,b\n', { header: true }), []);
  });

  it('stores a "__proto__" column as an own property', () => {
    const [record] = parse('__proto__,b\n1,2', { header: true });
    assert.deepEqual(Object.keys(record), ['__proto__', 'b']);
    assert.equal(Object.getOwnPropertyDescriptor(record, '__proto__').value, '1');
    assert.equal(Object.getPrototypeOf(record), Object.prototype);
  });

  it('reports a duplicate name where the second occurrence starts', () => {
    assertCsvError(() => parse('a,b,a\n1,2,3', { header: true }), 1, 5, /duplicate/i);
    assertCsvError(() => parse('a,"a"', { header: true }), 1, 3);
    assertCsvError(() => parse('"x\ny",b,b', { header: true }), 2, 6);
  });

  it('reports a duplicate empty name, including one that ends at end of input', () => {
    assertCsvError(() => parse(',', { header: true }), 1, 2);
    assertCsvError(() => parse('a,,', { header: true }), 1, 4);
  });

  it('allows the same name outside header mode and in data records', () => {
    assert.deepEqual(parse('a,a'), [['a', 'a']]);
    assert.deepEqual(parse('a,b\nx,x', { header: true }), [{ a: 'x', b: 'x' }]);
  });

  it('reports a record with fewer or more fields at its line, column 1', () => {
    assertCsvError(() => parse('a,b\n1,2\n3', { header: true }), 3, 1, /expected 2 fields but found 1/i);
    assertCsvError(() => parse('a,b\n1,2,3\n', { header: true }), 2, 1);
  });

  it('reports a multi-line record at the line where it starts', () => {
    assertCsvError(() => parse('a,b\n"x\ny"\n', { header: true }), 2, 1);
  });

  it('treats an empty line as a one-field record unless skipEmptyLines is set', () => {
    assertCsvError(() => parse('a,b\n\n1,2', { header: true }), 2, 1);
    assert.deepEqual(parse('a\n\nx', { header: true }), [{ a: '' }, { a: 'x' }]);
    assert.deepEqual(parse('\n\na,b\n\n1,2\n\n', { header: true, skipEmptyLines: true }), [
      { a: '1', b: '2' },
    ]);
  });

  it('checks a record field count only when the record ends', () => {
    // The short record ends at the LF, before the unclosed quote is read.
    assertCsvError(() => parse('a,b\nx,y,z\n"open', { header: true }), 2, 1);
    // The stray character comes before the record ends.
    assertCsvError(() => parse('a,b\n1,2,"3"x', { header: true }), 2, 8);
    // The duplicate name is complete before the stray character.
    assertCsvError(() => parse('a,a,"b"x', { header: true }), 1, 3);
  });
});

