'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { parse, createParser, stringify } = require('../src/csv.js');

function deepFreeze(value) {
  if (typeof value === 'object' && value !== null) {
    Object.values(value).forEach(deepFreeze);
    Object.freeze(value);
  }
  return value;
}

describe('stringify: arguments', () => {
  for (const [label, rows] of [
    ['undefined', undefined],
    ['null', null],
    ['a string', 'a,b'],
    ['an object', { 0: ['a'] }],
  ]) {
    it(`throws TypeError when rows is ${label}`, () => {
      assert.throws(() => stringify(rows), TypeError);
    });
  }

  it('throws TypeError for a row that is not an array', () => {
    assert.throws(() => stringify([['a'], 'b']), /Row 1 must be an array/);
    assert.throws(() => stringify([null]), TypeError);
    assert.throws(() => stringify([{ a: 1 }]), TypeError);
  });

  for (const [label, value] of [
    ['an object', { a: 1 }],
    ['an array', ['a']],
    ['a Date', new Date(0)],
    ['a symbol', Symbol('s')],
    ['a bigint', 1n],
    ['a function', () => 'x'],
  ]) {
    it(`throws TypeError for a value that is ${label}`, () => {
      assert.throws(() => stringify([['ok', value]]), /row 0, field 1/);
    });
  }

  for (const [label, delimiter] of [
    ['empty', ''],
    ['two characters', '||'],
    ['a double quote', '"'],
    ['CR', '\r'],
    ['LF', '\n'],
    ['null', null],
  ]) {
    it(`throws TypeError for a delimiter that is ${label}`, () => {
      assert.throws(() => stringify([['a']], { delimiter }), TypeError);
    });
  }

  for (const eol of ['\r', ';', '\n\r', '', null, 10]) {
    it(`throws TypeError for eol ${JSON.stringify(eol)}`, () => {
      assert.throws(() => stringify([['a']], { eol }), TypeError);
    });
  }

  it('validates options even when there are no rows', () => {
    assert.throws(() => stringify([], { eol: '\r' }), TypeError);
    assert.throws(() => stringify([], null), TypeError);
  });

  it('throws TypeError for a header that is not an array of strings', () => {
    assert.throws(() => stringify([], { header: true }), TypeError);
    assert.throws(() => stringify([], { header: 'a,b' }), TypeError);
    assert.throws(() => stringify([], { header: ['a', 1] }), /header\[1\]/);
  });

  it('does not modify rows, header or options', () => {
    const rows = deepFreeze([['a', ' b '], { x: 'q"' }]);
    const options = deepFreeze({ header: ['x', 'y'], eol: '\n' });
    assert.equal(stringify(rows, options), 'x,y\na," b "\n"q""",\n');
  });
});

describe('stringify: values and quoting', () => {
  it('writes strings as is and numbers and booleans via String()', () => {
    assert.equal(stringify([['a', 1, -2.5, 1e21, NaN, true, false]]), 'a,1,-2.5,1e+21,NaN,true,false\r\n');
  });

  it('writes null and undefined as empty fields, including array holes', () => {
    // eslint-disable-next-line no-sparse-arrays
    assert.equal(stringify([[null, 'a', undefined, , 'b']]), ',a,,,b\r\n');
  });

  it('quotes a field containing the delimiter, a quote, CR or LF', () => {
    assert.equal(stringify([['a,b', 'c"d', 'e\rf', 'g\nh']]), '"a,b","c""d","e\rf","g\nh"\r\n');
  });

  it('quotes a field that begins or ends with a space, but not other whitespace', () => {
    assert.equal(stringify([[' a', 'b ', ' ', 'c d', '\tx\t']]), '" a","b "," ",c d,\tx\t\r\n');
  });

  it('quotes by the configured delimiter', () => {
    assert.equal(stringify([['a;b', 'c,d']], { delimiter: ';' }), '"a;b";c,d\r\n');
    assert.equal(stringify([['a b', 'c']], { delimiter: ' ' }), '"a b" c\r\n');
  });

  it('doubles every quote inside a quoted field', () => {
    assert.equal(stringify([['"', '""', 'a "b" c']]), '"""","""""","a ""b"" c"\r\n');
  });

  it('writes a record whose only field is empty as ""', () => {
    assert.equal(stringify([[''], [null], ['a']]), '""\r\n""\r\na\r\n');
  });

  it('writes other empty fields unquoted', () => {
    assert.equal(stringify([['', ''], ['', 'a']]), ',\r\n,a\r\n');
  });

  it('writes an empty record as an empty line', () => {
    assert.equal(stringify([['a'], [], ['b']]), 'a\r\n\r\nb\r\n');
  });

  it('quotes a leading U+FEFF in the first field so parse does not drop it', () => {
    assert.equal(stringify([['﻿a', 'b'], ['﻿c']]), '"﻿a",b\r\n﻿c\r\n');
    assert.equal(stringify([['', 'a']], { delimiter: '﻿' }), '""﻿a\r\n');
  });

  it('keeps non-ASCII text', () => {
    assert.equal(stringify([['é', '\u{1F600}', '\uD800']]), 'é,\u{1F600},\uD800\r\n');
  });
});

describe('stringify: line endings', () => {
  it('joins records with CRLF by default and ends with one CRLF', () => {
    assert.equal(stringify([['a', 'b'], ['c', 'd']]), 'a,b\r\nc,d\r\n');
  });

  it('uses LF when eol is "\\n"', () => {
    assert.equal(stringify([['a'], ['b']], { eol: '\n' }), 'a\nb\n');
  });

  it('returns "" for no rows', () => {
    assert.equal(stringify([]), '');
    assert.equal(stringify([], { eol: '\n', delimiter: ';' }), '');
  });
});

describe('stringify: header', () => {
  it('writes the header row, then object values in header order', () => {
    const rows = [
      { name: 'Ada', id: 1 },
      { id: 2, name: 'Lin, Bo', extra: 'ignored' },
    ];
    assert.equal(stringify(rows, { header: ['id', 'name'] }), 'id,name\r\n1,Ada\r\n2,"Lin, Bo"\r\n');
  });

  it('writes a missing or inherited key as an empty field', () => {
    const inherited = Object.create({ b: 'from prototype' });
    inherited.a = 'x';
    assert.equal(stringify([{}, inherited], { header: ['a', 'b', 'toString'] }), 'a,b,toString\r\n,,\r\nx,,\r\n');
  });

  it('writes "" for a one-column object whose value is missing', () => {
    assert.equal(stringify([{}], { header: ['a'] }), 'a\r\n""\r\n');
  });

