describe('stringify and parse: round trip', () => {
  const optionSets = [];
  for (const delimiter of [undefined, ';', '\t', ' ', '"'.charCodeAt(0) ? '﻿' : '']) {
    for (const eol of [undefined, '\n']) {
      for (const skipEmptyLines of [false, true]) optionSets.push({ delimiter, eol, skipEmptyLines });
    }
  }

  it('returns the same rows for random non-empty rows of strings', () => {
    const random = mulberry32(4180);
    for (let run = 0; run < 3000; run++) {
      const rows = randomRows(random);
      for (const options of optionSets) {
        const text = stringify(rows, options);
        assert.deepEqual(parse(text, options), rows, `run ${run}: ${JSON.stringify({ rows, options })}`);
      }
    }
  });

  it('returns the same rows through createParser with random chunking', () => {
    const random = mulberry32(7);
    for (let run = 0; run < 1000; run++) {
      const rows = randomRows(random);
      const options = optionSets[run % optionSets.length];
      const parser = createParser(options);
      const records = [];
      for (const chunk of randomChunks(stringify(rows, options), random)) records.push(...parser.write(chunk));
      records.push(...parser.end());
      assert.deepEqual(records, rows, `run ${run}: ${JSON.stringify({ rows, options })}`);
    }
  });

  it('returns the same objects in header mode', () => {
    const header = ['id', 'note', ''];
    const objects = [
      { id: '1', note: 'multi\r\nline', '': '' },
      { id: '"2"', note: ' padded ', '': 'x,y' },
    ];
    const text = stringify(objects, { header });
    assert.deepEqual(parse(text, { header: true }), objects);
    assert.deepEqual(parse(stringify([], { header }), { header: true }), []);
  });

  it('turns values into the strings parse returns', () => {
    const text = stringify([[1, true, null, undefined, 'x']]);
    assert.deepEqual(parse(text), [['1', 'true', '', '', 'x']]);
  });
});

